SELECT * FROM (SELECT CASE WHEN city IN ('Berlin', 'Singapore') THEN 'core' ELSE 'other' END city_group, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END rating_bucket, ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_singapore FROM suppliers WHERE country = 'US' GROUP BY CASE WHEN city IN ('Berlin', 'Singapore') THEN 'core' ELSE 'other' END, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END) t WHERE pct_singapore < 52 ORDER BY pct_singapore DESC;
